F=/scratch/jjyeung/orch_n30/fb_pack; R=/scratch/jjyeung/orch_n30
mkdir -p $F/camrev; cp $R/sb_cursor_probe/AGENTS.md $F/camrev/AGENTS.md; echo  | base64 -d > $F/camrev/PROMPT.md; sha256sum $F/camrev/PROMPT.md
cd $F/camrev && tmux new-session -d -s fbp_camrev "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes. Write only REVIEW_VERDICT.md here.' > $F/camrev/cursor.log 2>&1" </dev/null >/dev/null 2>&1
sleep 3; tmux ls | grep fbp; date -u +%TZ; cat $F/cam/out/fbp_cam.tar.sha256
